/* ---------- Автосинхронизация в localStorage ---------- */
(function () {
  if (!window.LFLD_AUX_DATA) return;
  var A = window.LFLD_AUX_DATA;
  function mergeInto(key, value) {
    if (!value) return;
    try {
      var existing = JSON.parse(localStorage.getItem(key) || "null");
      var merged = (existing && typeof existing === "object")
        ? Object.assign({}, value, existing)
        : value;
      localStorage.setItem(key, JSON.stringify(merged));
    } catch (e) {}
  }
  mergeInto("ff_cup_metallist_rosters", A.cupMetallistRosters);
  mergeInto("ff_symbolic_teams",        A.symbolicTeams);
  mergeInto("ff_club_main_photo",       A.clubMainPhoto);
  mergeInto("ff_player_photos",         A.playerPhotos);
  mergeInto("ff_tournaments",           A.tournaments);
  if (Array.isArray(A.customClubs) && A.customClubs.length) {
    try { var cc = JSON.parse(localStorage.getItem("ff_custom_clubs") || "[]"); A.customClubs.forEach(function (c) { if (!c || !c.name) return; if (!cc.find(function (x) { return x.name === c.name; })) cc.push(c); }); localStorage.setItem("ff_custom_clubs", JSON.stringify(cc)); } catch (e) {}
  }
  if (Array.isArray(A.bannerSlides) && A.bannerSlides.length) {
    try { localStorage.setItem("bannerSlides", JSON.stringify(A.bannerSlides)); } catch (e) {}
  }
})();
